import java.util.Scanner;

public class GymMembership {
    private int memberId;
    private String memberName;
    private String packageType;
    private int durationMonths;
    private double fee;

    public GymMembership(int id, String name, String pkg, int months) {
        memberId = id;
        memberName = name;
        packageType = pkg.toUpperCase();
        durationMonths = months;
        fee = 0.0;
    }

    public void computeFee() {
        double monthlyRate;
        switch (packageType) {
            case "STANDARD":
                monthlyRate = 1200.0;
                break;
            case "PREMIUM":
                monthlyRate = 2000.0;
                break;
            case "VIP":
                monthlyRate = 3200.0;
                break;
            default:
                monthlyRate = 1000.0;
                System.out.println("Unknown package. Applied base rate Rs. 1000/mo.");
        }

        double baseFee = monthlyRate * durationMonths;
        double discountRate = 0.0;

        if (durationMonths >= 12) {
            discountRate = 0.20;
        } else if (durationMonths >= 6) {
            discountRate = 0.10;
        }

        fee = baseFee - (baseFee * discountRate);
    }

    public void printReceipt() {
        System.out.println("\n=========== FITLIFE MEMBERSHIP RECEIPT ===========");
        System.out.println("Member ID        : " + memberId);
        System.out.println("Member Name      : " + memberName);
        System.out.println("Package Selected : " + packageType);
        System.out.println("Duration         : " + durationMonths + " Months");
        System.out.println("Final Total Fee  : Rs. " + fee);
        System.out.println("==================================================");
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Member ID: ");
        int id = in.nextInt();
        in.nextLine(); // Clear newline
        System.out.print("Enter Member Name: ");
        String name = in.nextLine();
        System.out.print("Enter Package (STANDARD / PREMIUM / VIP): ");
        String pkg = in.nextLine();
        System.out.print("Enter Duration (in months): ");
        int months = in.nextInt();

        GymMembership member = new GymMembership(id, name, pkg, months);
        member.computeFee();
        member.printReceipt();
    }
}
```

