import java.util.Scanner;

public class ArraySignSegregation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int SIZE = 15;
        int[] original = new int[SIZE];
        int[] segregated = new int[SIZE];

        System.out.println("Enter " + SIZE + " integers (positive, negative, and zero):");
        for (int i = 0; i < SIZE; i++) {
            original[i] = sc.nextInt();
        }

        int negCount = 0, zeroCount = 0, posCount = 0;
        int idx = 0;

        // Pass 1: Copy all negative numbers
        for (int i = 0; i < SIZE; i++) {
            if (original[i] < 0) {
                segregated[idx++] = original[i];
                negCount++;
            }
        }

        // Pass 2: Copy all zeros
        for (int i = 0; i < SIZE; i++) {
            if (original[i] == 0) {
                segregated[idx++] = original[i];
                zeroCount++;
            }
        }

        // Pass 3: Copy all positive numbers
        for (int i = 0; i < SIZE; i++) {
            if (original[i] > 0) {
                segregated[idx++] = original[i];
                posCount++;
            }
        }

        System.out.println("\nOriginal Array:");
        for (int v : original) System.out.print(v + " ");
        System.out.println();

        System.out.println("\nSegregated Array (Negative -> Zero -> Positive):");
        for (int v : segregated) System.out.print(v + " ");
        System.out.println();

        System.out.println("\nSummary Statistics:");
        System.out.println("Negative Count = " + negCount);
        System.out.println("Zero Count     = " + zeroCount);
        System.out.println("Positive Count = " + posCount);
    }
}
```

