import java.util.Scanner;

public class CaesarCipher {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter plaintext message:");
        String message = in.nextLine();

        System.out.print("Enter shift key k (1 - 25): ");
        int k = in.nextInt();
        k = k % 26; // Normalize shift

        StringBuilder cipherText = new StringBuilder();

        for (int i = 0; i < message.length(); i++) {
            char ch = message.charAt(i);

            if (Character.isUpperCase(ch)) {
                char shifted = (char) ('A' + (ch - 'A' + k) % 26);
                cipherText.append(shifted);
            } else if (Character.isLowerCase(ch)) {
                char shifted = (char) ('a' + (ch - 'a' + k) % 26);
                cipherText.append(shifted);
            } else {
                cipherText.append(ch); // Non-alphabetic untouched
            }
        }

        System.out.println("\nPlaintext   : " + message);
        System.out.println("Key Shift   : " + k);
        System.out.println("Ciphertext  : " + cipherText.toString());
    }
}
```

