import java.util.Scanner;

public class EvilNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int num = sc.nextInt();

        if (num <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        // Convert to binary and count set bits
        int temp = num;
        String binaryStr = "";
        int onesCount = 0;

        while (temp > 0) {
            int rem = temp % 2;
            binaryStr = rem + binaryStr;
            if (rem == 1) {
                onesCount++;
            }
            temp /= 2;
        }

        System.out.println("\nDecimal Number : " + num);
        System.out.println("Binary Form    : " + binaryStr);
        System.out.println("Count of 1's   : " + onesCount);

        if (onesCount % 2 == 0) {
            System.out.println("\n" + num + " is an EVIL NUMBER (even number of 1's).");
        } else {
            System.out.println("\n" + num + " is an ODIOUS NUMBER (odd number of 1's).");
        }
    }
}
```

