import java.util.Scanner;

public class UpperAndLowerTriangularMatrix {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter dimension N of square matrix (3 to 6): ");
        int n = in.nextInt();

        if (n < 3 || n > 6) {
            System.out.println("Please enter N between 3 and 6.");
            return;
        }

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        System.out.println("\nOriginal Matrix:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.printf("%4d", mat[i][j]);
            }
            System.out.println();
        }

        System.out.println("\nUpper Triangular Matrix (on and above main diagonal):");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j >= i) {
                    System.out.printf("%4d", mat[i][j]);
                } else {
                    System.out.print("    "); // Blank space
                }
            }
            System.out.println();
        }

        int lowerSum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i > j) { // Strictly below main diagonal
                    lowerSum += mat[i][j];
                }
            }
        }

        System.out.println("\nSum of strictly Lower Triangular Elements = " + lowerSum);
    }
}
```

