import java.util.Scanner;

public class MenuPrimePalinFloyd {
    // Check prime helper
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    // Check palindrome helper
    public static boolean isPalindrome(int n) {
        int temp = n, rev = 0;
        while (temp > 0) {
            rev = rev * 10 + (temp % 10);
            temp /= 10;
        }
        return rev == n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== MATHEMATICAL UTILITIES MENU ==========");
        System.out.println("1. Prime Palindrome Number Check");
        System.out.println("2. Generate Floyd's Triangle");
        System.out.print("Enter your choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter a positive integer: ");
                int num = sc.nextInt();
                boolean p = isPrime(num);
                boolean pal = isPalindrome(num);

                System.out.println("Prime Status     : " + (p ? "YES" : "NO"));
                System.out.println("Palindrome Status: " + (pal ? "YES" : "NO"));

                if (p && pal) {
                    System.out.println(num + " is a PRIME PALINDROME NUMBER.");
                } else {
                    System.out.println(num + " is NOT a Prime Palindrome Number.");
                }
                break;

            case 2:
                System.out.print("Enter number of rows for Floyd's Triangle: ");
                int rows = sc.nextInt();
                if (rows <= 0) {
                    System.out.println("Rows must be greater than zero.");
                    break;
                }

                System.out.println("\nFloyd's Triangle (" + rows + " rows):");
                int val = 1;
                for (int i = 1; i <= rows; i++) {
                    for (int j = 1; j <= i; j++) {
                        System.out.printf("%4d", val++);
                    }
                    System.out.println();
                }
                break;

            default:
                System.out.println("Invalid Selection. Exiting.");
        }
    }
}
```

### Variable Description Table (VDT):

| Variable Name | Data Type | Purpose |
| :--- | :--- | :--- |
| `choice` | `int` | User menu option (1 or 2) |
| `num` | `int` | Integer tested for prime and palindrome |
| `p` | `boolean` | Result of prime check |
| `pal` | `boolean` | Result of palindrome check |
| `rows` | `int` | Total rows for Floyd's triangle |
| `val` | `int` | Running counter printed in Floyd's triangle |
| `i`, `j` | `int` | Row and column iteration indices |
| `sc` | `Scanner` | Input reader |
